import React, { useEffect, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { filter } from 'lodash';
import { useNavigate, useLocation } from 'react-router-dom';
import {
  Card,
  Table,
  Stack,
  Paper,
  Button,
  TableRow,
  TableBody,
  TableCell,
  Typography,
  IconButton,
  TableContainer,
  styled,
} from '@mui/material';
import Snackbar from '@mui/material/Snackbar';
import Alert from '@mui/material/Alert';
import AlertTitle from '@mui/material/AlertTitle';
import DateFormat from '../components/dayjsFormat/DateFormat';
import { axios } from '../utils/axios';
// components
import Iconify from '../components/iconify';
import Scrollbar from '../components/scrollbar';
// sections
import { UserListHead } from '../sections/@dashboard/user';
import { useMyContext } from './provider';
import GenerateToastConfig from '../components/toast-config/GenerateToastConfig';
import GoBackButton from '../components/goBackButton/GoBackButton';


export default function TransactionHistory({ id }) {
  const navigate = useNavigate();
  const location = useLocation();
  const { ids } = location.state || [];
  const [search, setsearch] = useState('');
  const [page, setPage] = useState(1);
  const [order, setOrder] = useState('asc');
  const [selected, setSelected] = useState([]);
  const [orderBy, setOrderBy] = useState('name');
  const [filterName, setFilterName] = useState('');
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [userList, setUserList] = useState([]);
  const [totalCount, setTotalCount] = useState(0);
  const { i18 } = useMyContext();

  const TABLE_HEAD = [
    { id: 'name', label: i18?.ACCOUNTSTITLE?.NAME || 'Name', alignRight: false },
    { id: 'balance', label: i18?.ACCOUNTSTITLE?.BALANCE || 'Balance', alignRight: false },
    { id: 'createdAt', label: i18?.ACCOUNTSTITLE?.CREATED_AT || 'CreatedAt', alignRight: false },
    { id: 'Type', label: i18?.ACCOUNTSTITLE?.TYPE || 'Type', alignRight: false },
    { id: 'total', label: i18?.ACCOUNTSTITLE?.TOTAL_TRANSACTION || 'Total Transaction', alignRight: false },
    { id: 'transactiondetails', label: i18?.ACCOUNTSTITLE?.TRANSACTION_DETAILS || 'Transaction Details', alignRight: false },
  ];

  const [verify, setVerify] = useState({
    open: false,
    vertical: 'top',
    horizontal: 'center',
  });

  const { vertical, horizontal, open } = verify;

  const fetchData = async () => {
    try {
      const res = await axios.get(`module/wallet/history?_page=${page}&_limit=${rowsPerPage}&userId=${id}`);
      if (res.status === 200) {
        setUserList(res.data.data.transaction);
        setTotalCount(res.data.data.totalCount);
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  useEffect(() => {
    fetchData();
  }, [page, rowsPerPage, order, orderBy, search]);

  const handleRequestSort = (event, property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  const handleSelectAllClick = (event) => {
    if (event.target.checked) {
      const newSelecteds = userList.map((n) => n.name);
      setSelected(newSelecteds);
      return;
    }
    setSelected([]);
  };

  const handlePush = (arr) => () => {
    navigate('/dashboard/Transactindetails', { state: { data: arr, ids } })
  }

  const backtouser = () => {
    navigate('/dashboard/user');
  };
  return (
    <>
      <Helmet>
        <title> TransactionHistory | Admin panel </title>
      </Helmet>

      <Stack direction="row" alignItems="center" justifyContent="space-between" mb={5}>
        <Typography variant="h4" gutterBottom>

          {i18?.ACCOUNTSTITLE?.TRANSACTION_HISTORY || "Transaction History"}
        </Typography>
        <GoBackButton
          label={i18?.ACCOUNTSTITLE?.GO_BACK || "Go Back"}
          onClick={backtouser}
          icon="icon-park-twotone:back"
        />
      </Stack>

      <Card>
        <Scrollbar>
          <TableContainer sx={{ minWidth: 800 }}>
            <Table>
              <UserListHead
                order={order}
                orderBy={orderBy}
                headLabel={TABLE_HEAD}
                rowCount={userList?.length}
                numSelected={selected?.length}
                onRequestSort={handleRequestSort}
                onSelectAllClick={handleSelectAllClick}
              />
              <TableBody>
                <TableRow
                  sx={{
                    '&:nth-of-type(odd)': {
                      backgroundColor: '#DDDDDD',
                    },
                    '&:last-child td, &:last-child th': {
                      border: 0,
                    },
                  }}
                  key={userList?._id}
                  tabIndex={-1}
                  role="checkbox"
                >
                  <TableCell padding="checkbox">
                    {/* <Checkbox checked={selectedUser} onChange={(event) => handleClick(event, name)} /> */}
                  </TableCell>
                  <TableCell align="left">{userList?.firstname} {userList.lastname}</TableCell>
                  <TableCell align="left">{userList?.balance ? userList.balance : '--'}</TableCell>
                  <TableCell align="left">{DateFormat(userList?.createdAt)}</TableCell>
                  <TableCell align="left">{userList?.userType ? userList.userType : '--'}</TableCell>
                  <TableCell align="left">{userList?.transactionCount ? userList.transactionCount : '--'}</TableCell>
                  <TableCell align="left">
                    <IconButton sx={{ mr: 2 }} onClick={handlePush(userList?.trx)}>
                      <Iconify icon={'carbon:view'} />
                    </IconButton></TableCell>
                </TableRow>

              </TableBody>
              {totalCount === 0 && (
                <TableBody>
                  <TableRow>
                    <TableCell align="center" colSpan={12} sx={{ py: 3 }}>
                      <Paper
                        sx={{
                          textAlign: 'center',
                        }}
                      >
                        <Typography variant="h6" paragraph>
                          No data found
                        </Typography>
                      </Paper>
                    </TableCell>
                  </TableRow>
                </TableBody>
              )}
            </Table>
          </TableContainer>
        </Scrollbar>
      </Card>

      <Snackbar
        anchorOrigin={{ vertical, horizontal }}
        autoHideDuration={3000}
        open={open}
        onClose={() => setVerify({ ...verify, open: false })}
        key={vertical + horizontal}
      >
        <Alert onClose={() => setVerify({ ...verify, open: false })} severity="success" sx={{ width: '100%' }}>
          <AlertTitle>Verified</AlertTitle>
        </Alert>
      </Snackbar>
    </>
  );
}
